#!/usr/bin/env python3
"""Seed-level summaries; physical losses and numerical censoring stay separate."""
import collections,csv,glob,json,math,pathlib,statistics,sys
stem=sys.argv[1];files=sorted(glob.glob(stem+'.shard*.jsonl')) or [stem+'.jsonl']
rows=[json.loads(l) for f in files for l in pathlib.Path(f).read_text().splitlines() if l.strip()]
keys=[(r['seed'],r['profile']) for r in rows];assert len(keys)==len(set(keys)),'duplicate seed/profile'
def mean(v):return statistics.mean(v) if v else None
def wilson(k,n):
 if not n:return None
 z=1.959963984540054;p=k/n;den=1+z*z/n;mid=(p+z*z/(2*n))/den;d=z*math.sqrt(p*(1-p)/n+z*z/(4*n*n))/den;return [mid-d,mid+d]
out={}
for profile in sorted({r['profile'] for r in rows}):
 a=[r for r in rows if r['profile']==profile];s=[r for r in a if r['stellarIntact']];unknown=[r for r in a if r['numericallyCensored']];known=[r for r in a if not r['numericallyCensored']]
 q={'n':len(a),'stellarSuccesses':len(s),'numericalUnknowns':len(unknown),'stellarRateObserved':len(s)/len(a),'wilsonKnownOnly':wilson(len(s),len(known)),'unknownWorstBestRate':[len(s)/len(a),(len(s)+len(unknown))/len(a)],'failures':dict(collections.Counter((r['starFailure'] or {}).get('kind','UNKNOWN' if r['numericallyCensored'] else 'complete') for r in a)),
 'stableAllSeedsMean':mean([r['stableFraction'] for r in a]),'stableSurvivorsMean':mean([r['stableFraction'] for r in s]),'matureStableSurvivorsMean':mean([r['matureStableFraction'] for r in s if r['matureStableFraction'] is not None]),'matureStableAllSeedsMean':mean([r['matureStableFraction'] for r in a if r['matureStableFraction'] is not None]),
 'planetOriginalSuccesses':sum(r['originalPlanetSurvived'] for r in a),'planetLossesTotal':sum(r['planetLosses'] for r in a),'planetLossesMean':mean([r['planetLosses'] for r in a]),'absentFractionMean':mean([r['absentFraction'] for r in a]),'civilizationBirthsTotal':sum(r['civilizationBirths'] for r in a),'civilizationDeathsTotal':sum(r['civilizationDeaths'] for r in a),'civilizationAliveMean':mean([r['civilizationAliveFraction'] for r in a]),
 'nonhierSurvivorsMean':mean([r['nonhierFraction'] for r in s]),'longestGeometricHierarchySurvivorsMean':mean([r['longestHierarchyYears'] for r in s]),'dynamicalHierarchySurvivorsMean':mean([r['dynHierFraction'] for r in s if 'dynHierFraction' in r]),'longestDynamicalHierarchySurvivorsMax':max([r.get('longestDynamicalHierarchyYears',0) for r in s],default=None),'conditionalFTLESurvivors':[(r['seed'],r.get('matureConditionalFTLE')) for r in s],'tightExchangesSurvivorsMean':mean([r['tightPairChanges'] for r in s if 'tightPairChanges' in r]),
 'controlSignedWorkOverE0Mean':mean([r['control']['work']/abs(r.get('initialEnergy',1)) for r in a]),'controlGrossWorkOverE0Mean':mean([r['control']['absoluteWork']/abs(r.get('initialEnergy',1)) for r in a]),'controlImpulseMean':mean([r['control']['impulse'] for r in a]),'controlActiveFrameFractionMean':mean([r['controlActiveFrameFraction'] for r in a if 'controlActiveFrameFraction' in r]),'controlPeakAccelerationMax':max(r['control']['peakAcceleration'] for r in a),'controlPeakVelocityJumpMax':max(r['control'].get('peakVelocityJump',0) for r in a),'maxNumericalEnergyResidual':max(r['maxNumericalEnergyResidual'] for r in a),'wallSecondsTotal':sum(r['wallSeconds'] for r in a),'maxRSSMiB':max(r.get('maxRSSKiB',0) for r in a)/1024}
 q['survivorDistribution']={r['seed']:{k:r.get(k) for k in ['stableFraction','matureStableFraction','nonhierFraction','matureNonhierFraction','dynHierFraction','longestDynamicalHierarchyYears','planetLosses','matureConditionalFTLE','tightPairChanges','controlActiveFrameFraction']} for r in s};out[profile]=q
pathlib.Path(stem+'.summary.json').write_text(json.dumps({'files':files,'groups':out},indent=2)+'\n')
fields=['seed','profile','horizon','integratedYears','stellarIntact','starFailure','numericallyCensored','stableFraction','matureStableFraction','nonhierFraction','dynHierFraction','longestDynamicalHierarchyYears','matureConditionalFTLE','tightPairChanges','planetLosses','planetRespawns','absentFraction','civilizationBirths','civilizationDeaths','civilizationAliveFraction','controlActiveFrameFraction','maxNumericalEnergyResidual','steps','wallSeconds','maxRSSKiB']
with open(stem+'.seeds.csv','w') as f:
 w=csv.DictWriter(f,fieldnames=fields);w.writeheader();w.writerows({k:json.dumps(r[k]) if k in ['starFailure'] else r.get(k) for k in fields} for r in rows)
for p,r in out.items():print(f"{p:20} stars {r['stellarSuccesses']:3}/{r['n']} unknown {r['numericalUnknowns']} stable {r['stableAllSeedsMean']:.3f} mature {r['matureStableSurvivorsMean']} nonhier {r['nonhierSurvivorsMean']} active {r['controlActiveFrameFractionMean']} grossW/E {r['controlGrossWorkOverE0Mean']:.2f} residual {r['maxNumericalEnergyResidual']:.2g}")
